use std::ffi::OsStr;
use std::path::Path;

use crate::error::*;

pub const IGNORED_SUFFIXES: [&str; 13] = [
    // Editor etc backups
    "~",
    ".bak",
    ".old",
    ".orig",
    // Debian and derivatives apt/dpkg/ucf backups
    ".dpkg-dist",
    ".dpkg-old",
    ".ucf-dist",
    ".ucf-new",
    ".ucf-old",
    // Red Hat and derivatives rpm backups
    ".rpmnew",
    ".rpmorig",
    ".rpmsave",
    // Build system input/template files
    ".in",
];

#[derive(Debug, Clone)]
pub(crate) struct IgnoredSuffixes<'a> {
    pub(crate) values: Vec<&'a str>,
}

impl<'a> Default for IgnoredSuffixes<'a> {
    fn default() -> Self {
        Self {
            values: IGNORED_SUFFIXES.to_vec(),
        }
    }
}

impl<'a> IgnoredSuffixes<'a> {
    pub(crate) fn add_suffix(&mut self, suffix: &'a str) {
        if !suffix.is_empty() {
            self.values.push(suffix);
        }
    }

    pub(crate) fn strip_suffix<'b>(&self, file_name: &'b str) -> Option<&'b str> {
        self.values
            .iter()
            .find_map(|suffix| file_name.strip_suffix(suffix))
    }
}

/// If we find an ignored suffix on the file name, e.g. '~', we strip it and
/// then try again without it.
pub fn try_with_stripped_suffix<T, F>(
    file_name: &OsStr,
    ignored_suffixes: &IgnoredSuffixes,
    func: F,
) -> Result<Option<T>>
where
    F: Fn(&OsStr) -> Result<Option<T>>,
{
    let mut from_stripped = None;
    if let Some(file_str) = Path::new(file_name).to_str() {
        if let Some(stripped_filename) = ignored_suffixes.strip_suffix(file_str) {
            from_stripped = func(OsStr::new(stripped_filename))?;
        }
    }
    Ok(from_stripped)
}
    pub fn insert(&mut self, from: &str, to: MappingTarget<'a>) -> Result<()> {
        let glob = GlobBuilder::new(from)
            .case_insensitive(false)
            .literal_separator(true)
            .build()?;
        self.mappings.push((glob.compile_matcher(), to));
        Ok(())
    }

    pub fn mappings(&self) -> &[(GlobMatcher, MappingTarget<'a>)] {
        &self.mappings
    }

    pub fn insert_ignored_suffix(&mut self, suffix: &'a str) {
        self.ignored_suffixes.add_suffix(suffix);
    }

    pub(crate) fn get_syntax_for(&self, path: impl AsRef<Path>) -> Option<MappingTarget<'a>> {
        let path = path.as_ref();

        if let Some(mapping) = self.get_syntax_for_exact(path) {
            return Some(mapping);
        }

        let mut file_name = path.file_name()?.to_str()?;
        while let Some(stripped_file_name) = self.ignored_suffixes.strip_suffix(file_name) {
            if let Some(mapping) =
                self.get_syntax_for_exact(&path.with_file_name(stripped_file_name))
            {
                return Some(mapping);
            }
            file_name = stripped_file_name;
        }

        None
    }

    fn get_syntax_for_exact(&self, path: &Path) -> Option<MappingTarget<'a>> {
        let candidate = Candidate::new(path);
        let candidate_filename = path.file_name().map(Candidate::new);
        for (ref glob, ref syntax) in self.mappings.iter().rev() {
            if glob.is_match_candidate(&candidate)
                || candidate_filename
                    .as_ref()
                    .map_or(false, |filename| glob.is_match_candidate(filename))
            {
                return Some(*syntax);
            }
        }
        None
    }
}

#[test]
fn basic() {
    let mut map = SyntaxMapping::empty();
    map.insert("/path/to/Cargo.lock", MappingTarget::MapTo("TOML"))
        .ok();
    map.insert("/path/to/.ignore", MappingTarget::MapTo("Git Ignore"))
        .ok();

        let syntax_set = self.get_syntax_set()?;
        let extension = e.and_then(|x| x.to_str()).unwrap_or_default();
        Ok(syntax_set
            .find_syntax_by_extension(extension)
            .map(|syntax| SyntaxReferenceInSet { syntax, syntax_set }))
    }

    fn get_syntax_for_file_name(
        &self,
        file_name: &OsStr,
        mapping: &SyntaxMapping,
    ) -> Result<Option<SyntaxReferenceInSet>> {
        let mut syntax = self.find_syntax_by_extension(Some(file_name))?;
        if syntax.is_none() {
            syntax = try_with_stripped_suffix(
                file_name,
                &mapping.ignored_suffixes,
                |stripped_file_name| {
                    self.get_syntax_for_file_name(stripped_file_name, mapping) // Note: recursion
                },
            )?;
        }
        Ok(syntax)
    }

    fn get_syntax_for_file_extension(
        &self,
        file_name: &OsStr,
        mapping: &SyntaxMapping,
    ) -> Result<Option<SyntaxReferenceInSet>> {
        let mut syntax = self.find_syntax_by_extension(Path::new(file_name).extension())?;
        if syntax.is_none() {
            syntax = try_with_stripped_suffix(
                file_name,
                &mapping.ignored_suffixes,
                |stripped_file_name| {
                    self.get_syntax_for_file_extension(stripped_file_name, mapping) // Note: recursion
                },
            )?;
        }
        Ok(syntax)
    }
}

